import React, { useState } from 'react';
import { Stat, PageTitle, Field, Modal, Status, Empty } from '../common';
import './SiteVisitsPage.css';

export default function SiteVisitsPage({leads}) { const visits=leads.filter(l=>l.status==='Site Visit'); return <div className="module-page module-page--site-visits"><PageTitle eyebrow="FIELD SALES" title="Site visits" subtitle="Coordinate buyer visits and capture the next action after every tour."/><div className="stats-grid"><Stat label="Visits in pipeline" value={visits.length} change="Lead stage based" icon="⌖" tone="purple" foot="Schedule confirmations"/><Stat label="Need scheduling" value={visits.filter(l=>!l.next||l.next==='Not scheduled').length} change="Action required" icon="◷" tone="orange" foot="Confirm with customer"/><Stat label="Assigned agents" value={new Set(visits.map(l=>l.assigned)).size} change="Team coverage" icon="♙" tone="blue" foot="Across current visits"/><Stat label="Visit outcomes" value="—" change="Not yet captured" icon="✓" tone="green" foot="Add backend visit outcomes"/></div><div className="panel"><div className="panel-head"><div><h3>Visit schedule queue</h3><p>Current leads marked as Site Visit</p></div></div><div className="table-wrap"><table><thead><tr><th>BUYER</th><th>LOCATION / TYPE</th><th>AGENT</th><th>PLANNED DATE</th><th>FOLLOW-UP</th></tr></thead><tbody>{visits.map(l=><tr key={l.id}><td><b>{l.name}</b><small className="cell-sub">{l.phone}</small></td><td>{l.location}<small className="cell-sub">{l.type}</small></td><td>{l.assigned}</td><td>{l.next}</td><td>{l.notes||'Capture visit feedback'}</td></tr>)}</tbody></table></div></div></div>; }
